import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('contains unrelated configuration that adapters must preserve', async () => {
  const opencode = await readFile(new URL('../.opencode/opencode.json', import.meta.url), 'utf8');
  const claude = await readFile(new URL('../.claude/settings.json', import.meta.url), 'utf8');
  assert.match(opencode, /example\.invalid/);
  assert.match(opencode, /user-theme/);
  assert.match(claude, /user-owned-hook/);
});
